const rawInput = $input.first().json;
const input = rawInput.body || rawInput;
const prompt = input.prompt || 'cinematic footage, dynamic camera movement, high quality, detailed';
const negative = input.negative_prompt || 'blurry, watermark, text, static, no movement, low quality, ugly';
const width = input.width || 832;
const height = input.height || 480;
const num_frames = input.num_frames || 81;
const seed = input.seed != null ? input.seed : Math.floor(Math.random() * 999999999);
const steps = input.steps || 20;
const cfg = input.cfg || 6.0;
const frame_rate = input.frame_rate || 16;

const modelKey = input.model || 'wan22-14b-fp8';
const MODELS = {
  'wan22-14b-fp8': 'Wan2_2-Animate-14B_fp8_e4m3fn_scaled_KJ.safetensors',
  'wan22-5b-fp16': 'wan2.2_ti2v_5B_fp16.safetensors'
};
const unetModel = MODELS[modelKey] || MODELS['wan22-14b-fp8'];

const workflow = {
  '1': {class_type: 'UNETLoader', inputs: {unet_name: unetModel, weight_dtype: 'default'}},
  '2': {class_type: 'CLIPLoader', inputs: {clip_name: 'umt5_xxl_fp8_e4m3fn_scaled.safetensors', type: 'wan'}},
  '3': {class_type: 'VAELoader', inputs: {vae_name: 'wan2.2_vae.safetensors'}},
  '4': {class_type: 'CLIPTextEncode', inputs: {text: prompt, clip: ['2', 0]}},
  '5': {class_type: 'CLIPTextEncode', inputs: {text: negative, clip: ['2', 0]}},
  '6': {class_type: 'WanImageToVideo', inputs: {positive: ['4', 0], negative: ['5', 0], vae: ['3', 0], width, height, length: num_frames, batch_size: 1}},
  '7': {class_type: 'KSampler', inputs: {model: ['1', 0], positive: ['6', 0], negative: ['6', 1], latent_image: ['6', 2], seed, steps, cfg, sampler_name: 'euler', scheduler: 'beta', denoise: 1.0}},
  '8': {class_type: 'VAEDecode', inputs: {samples: ['7', 0], vae: ['3', 0]}},
  '9': {class_type: 'VHS_VideoCombine', inputs: {images: ['8', 0], frame_rate, loop_count: 0, filename_prefix: 'openm_wan22', format: 'video/h264-mp4', pingpong: false, save_output: true}},
};

return [{json: {workflow: JSON.stringify(workflow), seed, prompt, unetModel, num_frames, frame_rate}}];

const http = require('http');
const comfyUrl = '172.25.0.1';
const comfyPort = 8188;
const promptId = $input.first().json.prompt_id;
const seed = $('Build Wan 2.2 Workflow').first()?.json?.seed;
const prompt = $('Build Wan 2.2 Workflow').first()?.json?.prompt;
const num_frames = $('Build Wan 2.2 Workflow').first()?.json?.num_frames;

if (!promptId) throw new Error('No prompt_id from ComfyUI submit');

function httpGet(path) {
  return new Promise((resolve, reject) => {
    const req = http.get({ hostname: comfyUrl, port: comfyPort, path }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch(e) { reject(e); }
      });
    });
    req.on('error', reject);
    req.setTimeout(10000, () => { req.abort(); reject(new Error('timeout')); });
  });
}

for (let i = 0; i < 1800; i++) {
  await new Promise(r => setTimeout(r, 1000));
  const history = await httpGet(`/history/${promptId}`);
  const result = history[promptId];
  if (!result) continue;

  if (result?.status?.status_str === 'error') {
    const msgs = result.status.messages || [];
    const errMsg = msgs.find(m => m[0] === 'execution_error');
    throw new Error(`ComfyUI error: ${JSON.stringify(errMsg || msgs)}`);
  }

  if (result?.status?.completed) {
    for (const nodeOut of Object.values(result.outputs || {})) {
      const files = nodeOut.videos || nodeOut.images || [];
      if (files.length > 0) {
        const f = files[0];
        const qs = `filename=${encodeURIComponent(f.filename)}&subfolder=${encodeURIComponent(f.subfolder||'')}&type=${f.type||'output'}`;
        return [{json: {
          success: true,
          filename: f.filename,
          subfolder: f.subfolder || '',
          type: f.type || 'output',
          download_url: `http://${comfyUrl}:${comfyPort}/view?${qs}`,
          prompt_id: promptId,
          seed,
          prompt,
          num_frames
        }}];
      }
    }
    throw new Error('ComfyUI completed but no video output found');
  }
}
throw new Error('Video generation timed out after 30 minutes');
